from dataclasses import dataclass, replace
from functools import partial


@dataclass(frozen=True)
class Item:
    name: str
    price: float
    qty: int


Cart = tuple[Item, ...]


def add_item(cart: Cart, item: Item) -> Cart:
    if item.price < 0:
        raise ValueError(f"Отрицательная цена у товара {item.name}")
    if any(i.name == item.name for i in cart):
        return tuple(replace(i, qty=i.qty + item.qty) if i.name == item.name else i for i in cart)
    return cart + (item,)


def remove_item(cart: Cart, name: str) -> Cart:
    if all(i.name != name for i in cart):
        raise ValueError(f"Товара {name} нет в корзине")
    return tuple(i for i in cart if i.name != name)


def change_qty(cart: Cart, name: str, qty: int) -> Cart:
    if qty <= 0:
        return remove_item(cart, name)
    if all(i.name != name for i in cart):
        raise ValueError(f"Товара {name} нет в корзине")
    return tuple(replace(i, qty=qty) if i.name == name else i for i in cart)


def apply_discount(cart: Cart, percent: float) -> Cart:
    if not 0 <= percent <= 100:
        raise ValueError("Скидка должна быть от 0 до 100")
    return tuple(replace(i, price=i.price * (100 - percent) / 100) for i in cart)


def total(cart: Cart) -> float:
    return sum(i.price * i.qty for i in cart)


def apply_operations(cart: Cart, operations: tuple) -> tuple[Cart, ...]:
    history = (cart,)
    for operation in operations:
        history = history + (operation(history[-1]),)
    return history


def print_history(history: tuple[Cart, ...]) -> None:
    print(f"{'Шаг':<5}| {'Состав корзины':<80}| {'Сумма':>10}")
    print("-" * 100)
    for step, cart in enumerate(history):
        items = ", ".join(f"{i.name} x{i.qty} ({i.price:g})" for i in cart)
        print(f"{step:<5}| {items:<80}| {total(cart):>10.0f}")


if __name__ == "__main__":
    initial_cart = (
        Item("Ноутбук", 350_000, 1),
        Item("Мышь", 8_000, 2),
        Item("Клавиатура", 15_000, 1),
    )
    initial_copy = tuple(initial_cart)

    operations = (
        partial(add_item, item=Item("Наушники", 25_000, 1)),
        partial(remove_item, name="Мышь"),
        lambda cart: change_qty(cart, "Клавиатура", 2),
        lambda cart: apply_discount(cart, 10),
    )

    history = apply_operations(initial_cart, operations)
    print_history(history)

    assert len(history) == 5
    assert [total(c) for c in history] == [381000, 406000, 390000, 405000, 364500]
    assert total(initial_cart) == 381000
    assert initial_cart == initial_copy
    assert history[0] is initial_cart
    assert len({id(c) for c in history}) == len(history)

    with_mouse = add_item(initial_cart, Item("Мышь", 8000, 1))
    mice = [i for i in with_mouse if i.name == "Мышь"]
    assert len(mice) == 1 and mice[0].qty == 3

    assert change_qty(initial_cart, "Мышь", 0) == remove_item(initial_cart, "Мышь")

    for bad_call in (
        lambda: apply_discount(initial_cart, 150),
        lambda: apply_discount(initial_cart, -5),
        lambda: remove_item(initial_cart, "Телефон"),
        lambda: add_item(initial_cart, Item("Чехол", -100, 1)),
    ):
        try:
            bad_call()
            assert False
        except ValueError:
            pass

    assert initial_cart == initial_copy
    print()
    print("Все проверки пройдены")

